sys_variable_value.value:
(function execute(inputs, outputs) {
    
    const api = new x_neyu_google_nyu.LicenseAPI();
    const response = api.delete(
        inputs.productId,
        inputs.skuId,
        inputs.userId
    );

    outputs.error = response.error;
    outputs.error_message = response.errorMessage;

    if (!response.error) {
        outputs.status = response.status;
        const isNon2XX = parseInt(response.status / 100) != 2;
        if (isNon2XX && response.hasOwnProperty("responseBody")) {
            outputs.error_response = JSON.parse(response.responseBody);
        }
    }
    
})(inputs, outputs);

